package com.campusnova.service; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class SemanticTextServiceTest { private final SemanticTextService semantic=new SemanticTextService(); @Test void recognizesTimingLanguageAsRelated(){assertTrue(semantic.score("when does the library close",Collections.<String>emptyList(),"library hours and timings")>=.2);}@Test void preservesConversationTermsForFollowUps(){assertTrue(semantic.score("is it open saturday",Collections.singletonList("library timings"),"library opening hours")>.2);}@Test void lostIdDoesNotHaveEnoughOverlapWithAdmissionDocuments(){String q="What should a student do if they lose their college ID card?";String admission="Admission documents include mark sheets, ID proof and photographs.";assertEquals(1,semantic.overlap(q,Collections.emptyList(),admission));assertFalse(semantic.hasStrongTopicMatch(q,admission));}}
